#include "multicamera_joint.h"
#include <gtest/gtest.h>
using namespace fastlivo_multicamera;
StatesGroup prior(){StatesGroup s;s.cov.setIdentity();s.cov(0,6)=s.cov(6,0)=.4;return s;}
std::array<Factor,4> factors(){std::array<Factor,4> f;for(auto &a:f){a.pixels=64;a.information.setIdentity();a.information*=20.;a.information(0,6)=a.information(6,0)=3.;}return f;}
TEST(MulticameraJoint,NativePhysicalMarginalDoesNotConditionOnExposure){auto s=prior();auto p=physical_marginal(s);EXPECT_DOUBLE_EQ(p(0,0),1.);EXPECT_DOUBLE_EQ(independent_image_prior(s).cov(0,0),1.);EXPECT_DOUBLE_EQ(independent_image_prior(s).cov(0,6),0.);}
TEST(MulticameraJoint,ClonedCorrelatedFactorsDoNotMultiplyPhysicalInformation){auto s=prior();auto f=factors();auto o=solve(s,f);Physical expected=Physical::Identity();Eigen::Matrix<double,6,6> h=f[0].information.topLeftCorner<6,6>()-f[0].information.block<6,1>(0,6)*(1./30.)*f[0].information.block<1,6>(6,0);expected.topLeftCorner<6,6>()+=h;expected=expected.inverse().eval();EXPECT_LT((o.physical_covariance-expected).cwiseAbs().maxCoeff(),1e-12);EXPECT_GT(o.physical_covariance(0,0),1./(1.+4.*20.));}
TEST(MulticameraJoint,PrivateExposureNotCopiedBetweenCameras){auto f=factors();f[1].gradient[6]=.2;auto o=solve(prior(),f);EXPECT_NE(o.cameras[0].inv_expo_time,o.cameras[1].inv_expo_time);for(int i=0;i<4;++i){EXPECT_EQ(Eigen::LLT<decltype(o.cameras[i].cov)>(o.cameras[i].cov).info(),Eigen::Success);EXPECT_LT((physical_marginal(o.cameras[i])-o.physical_covariance).norm(),1e-12);}}
TEST(MulticameraJoint,MissingNonfiniteOrIndefiniteFactorsReject){for(int mode=0;mode<3;++mode){auto f=factors();if(mode==0)f[2].pixels=0;if(mode==1)f[2].gradient[0]=NAN;if(mode==2)f[2].information(0,0)=-100.;EXPECT_THROW(solve(prior(),f),std::exception);}}
TEST(MulticameraJoint,UninformativeFactorsPreservePhysicalPrior){auto f=factors();for(auto &a:f)a.information.setZero();auto o=solve(prior(),f);EXPECT_LT((o.physical_covariance-physical_marginal(prior())).norm(),1e-12);EXPECT_EQ(o.physical_increment.norm(),0.);}
TEST(MulticameraJoint,NonzeroRotationUpdatesStateAndTransportsCovariance){auto f=factors();for(auto&a:f)a.gradient[1]=.1;auto o=solve(prior(),f);EXPECT_GT(o.physical_increment.head<3>().norm(),0.);EXPECT_LT((o.cameras[0].rot_end.transpose()*o.cameras[0].rot_end-M3D::Identity()).norm(),1e-12);EXPECT_EQ(Eigen::LLT<Physical>(o.physical_covariance).info(),Eigen::Success);}
